WHERE is_active = 1 AND is_provident_fund = 1 AND id NOT IN (SELECT employee_id FROM provident_fund_details WHERE is_active = 1 AND status = 1)
AND ( (employees.name_en LIKE #{filter.searchText}) OR (employees.name_kh LIKE #{filter.searchText}) OR (employees.code LIKE #{filter.searchText}) )
AND employees.id = #{filter.employeeId}

mapper.select:
SELECT



ORDER BY


        ${filter.orderBy}


        id DESC


LIMIT #{filter.page}, #{filter.rowsPerPage}

SELECT id, `date`, historyAmount FROM ( SELECT pd.id AS id, DATE_FORMAT(p.pay_date, "%d-%b-%Y") AS `date`, CONCAT_WS('', '+', pd.amount, '$') AS historyAmount, p.pay_date AS sort_date FROM payrolls AS p INNER JOIN payroll_details AS pd ON p.id = pd.payroll_id WHERE p.is_active = 1 AND pd.is_active = 1 AND pd.payroll_item_id = 10 AND pd.amount > 0 AND p.employee_id = #{employeesId} AND p.pay_date <= #{filterMonth}
UNION ALL
SELECT pfd.id AS id, DATE_FORMAT(pf.request_date, "%d-%b-%Y") AS `date`, CONCAT_WS('', '-', pfd.amount, '$') AS historyAmount, pf.request_date AS sort_date FROM provident_funds AS pf INNER JOIN provident_fund_details AS pfd ON pf.id = pfd.provident_fund_id WHERE pfd.is_active = 1 AND pfd.status = 2 AND pfd.employee_id = #{employeesId} AND pf.date < #{filterMonth} ) AS history ORDER BY sort_date DESC

