UPDATE provident_funds SET
    status = #{providentFundUpdateStatus.status},
    modified = NOW(),
    modified_by = #{providentFundUpdateStatus.modifiedBy}
WHERE id = #{providentFundUpdateStatus.id};

UPDATE provident_funds SET
    amount_request = (SELECT COALESCE(SUM(amount),0) FROM provident_fund_details WHERE provident_fund_id = #{providentFundUpdateStatus.id} AND is_active = 1)
WHERE id = #{providentFundUpdateStatus.id};

UPDATE provident_funds SET
    modified = NOW(),
    modified_by = #{providentFundRequestStatus.modifiedBy}
WHERE is_active = 1 AND id = #{providentFundRequestStatus.providentFundId}

UPDATE provident_fund_details SET
    status = #{providentFundRequestStatusByEmp.status},
    modified = NOW(),
    modified_by = #{providentFundRequestStatusByEmp.modifiedBy}
WHERE is_active = 1 AND provident_fund_id = #{proFundId} AND employee_id = #{providentFundRequestStatusByEmp.employeesId}

