SELECT id AS id, code AS empId, name_kh AS nameKh, name_en AS nameEn, department_id AS departmentId, (SELECT name FROM departments WHERE is_active = 1 AND id = department_id) AS departmentName FROM employees WHERE is_active = 1 AND is_provident_fund = 1
AND employees.department_id IN (SELECT id FROM departments WHERE is_active = 1 AND group_id = #{filter.groupId})
LIMIT #{filter.page}, #{filter.rowsPerPage}
